import heapq

def match(orders):
    trades = []
    book = {}  # id -> [side, price, qty, time, active]
    buy_heap = []   # entries: (-price, time, id)
    sell_heap = []  # entries: (price, time, id)

    time_counter = 0

    def clean_buy_heap():
        while buy_heap:
            negprice, t, oid = buy_heap[0]
            if oid not in book:
                heapq.heappop(buy_heap)
                continue
            entry = book[oid]
            if not entry[4] or entry[2] <= 0:
                heapq.heappop(buy_heap)
                continue
            break

    def clean_sell_heap():
        while sell_heap:
            price, t, oid = sell_heap[0]
            if oid not in book:
                heapq.heappop(sell_heap)
                continue
            entry = book[oid]
            if not entry[4] or entry[2] <= 0:
                heapq.heappop(sell_heap)
                continue
            break

    for order in orders:
        time_counter += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                entry = book[oid]
                if entry[4] and entry[2] > 0:
                    entry[4] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                sp, st, sid = sell_heap[0]
                if price is not None and sp > price:
                    break
                entry = book[sid]
                resting_qty = entry[2]
                trade_qty = min(remaining, resting_qty)
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                entry[2] -= trade_qty
                if entry[2] <= 0:
                    entry[4] = False
                    heapq.heappop(sell_heap)
                else:
                    # partially filled, stays at front conceptually, but heap top unchanged in price/time
                    # need to not pop, but since we only peeked, it's fine, loop continues without popping
                    if remaining <= 0:
                        break
                    # if resting order still has qty but our remaining exhausted, we already broke
                    # if remaining > 0 still, this shouldn't happen since trade_qty = min(...)
                    pass
        else:  # sell
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                negbp, bt, bid = buy_heap[0]
                bp = -negbp
                if price is not None and bp < price:
                    break
                entry = book[bid]
                resting_qty = entry[2]
                trade_qty = min(remaining, resting_qty)
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                entry[2] -= trade_qty
                if entry[2] <= 0:
                    entry[4] = False
                    heapq.heappop(buy_heap)
                else:
                    if remaining <= 0:
                        break
                    pass

        if typ == 'limit' and remaining > 0:
            book[oid] = [side, price, remaining, time_counter, True]
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, time_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, time_counter, oid))
        # ioc and market discard remaining

    return trades

